-- Seed: the briefings the client already e-mailed by hand.
-- Marked published AND sent so the dispatcher never re-sends them.
-- Source data: src/data/briefings/*.json

INSERT INTO public.briefings (slug, ref, briefing_date, title, content, status, source, sent_at)
VALUES ('2026-11-02', 'TAG/DB/2026/061', '2026-11-02', 'TAG Daily Briefing — 02 November 2026', $json${"date":"2026-11-02","ref":"TAG/DB/2026/061","topics":["Income Tax","GST","Securities Regulation","Growth Capital","Global Markets"],"executive_summary":["Gujarat High Court confirms that export commission for offshore services is outside Indian withholding where the recipient has no Indian business connection.","Reopening beyond three years fails once the accepted escaped income falls below the ₹50 lakh threshold in Section 149(1)(b).","CBIC’s 30 October instruction immediately restrains Central GST arrests, random transit checks and sub-₹10,000 demand notices pending legislation.","GSTAT Hyderabad preserves a ₹61.47 lakh inverted-duty refund relating to credit accumulated before 18 July 2022, despite a later filing date."],"items":[{"section":"Tax & Regulatory","subsection":"INCOME TAX","category":"International Tax","title":"Offshore export commission escapes Indian withholding where no income is chargeable here","body":"In PCIT v. DML Exim Pvt. Ltd., Tax Appeals 115 and 116 of 2021, the Gujarat High Court on 21 October 2026 upheld deletion of Section 40(a)(ia) disallowances of ₹21.61 crore and ₹9.73 crore. The non-resident agents solicited export orders and rendered services outside India; the receipts were business income, not fees for technical services, and the recipients had no Indian business connection. Section 195 therefore did not require withholding because the sums were not chargeable to tax in India.","why_it_matters":"The ruling reinforces the chargeability test for cross-border commission, but the protection remains fact-dependent and does not extend to functions performed in India or services with a technical character.","action_point":"Exporters should preserve agent agreements, territorial scope, correspondence, invoices, residency evidence and a PE/business-connection analysis before remitting commission without tax.","source_label":"Gujarat High Court order","source_url":null},{"section":"Tax & Regulatory","subsection":"INCOME TAX","category":"Reassessment","title":"Section 149 threshold must be tested against the income ultimately accepted by the Assessing Officer","body":"The Gujarat High Court quashed a 23 March 2023 notice and order reopening AY 2016–17 beyond three years. Although the initial information treated the full ₹6.27 crore property consideration as the taxpayer’s, the Assessing Officer later accepted her 6.25% share and computed alleged escaped long-term capital gain at ₹37.55 lakh. The Court held that the officer had to drop proceedings once the accepted escapement fell below the ₹50 lakh threshold in Section 149(1)(b); initial non-response did not cure the limitation defect.","why_it_matters":"A gross transaction value or third-party data point cannot sustain an extended reopening period if the taxpayer-specific income potentially escaping assessment is below the statutory floor.","action_point":"For notices issued after three years, reconcile ownership shares, TDS statements and the exact income alleged to have escaped, and raise limitation at the first available stage.","source_label":"Full judgment and case analysis","source_url":null},{"section":"Tax & Regulatory","subsection":"GST & INDIRECT TAX","category":"GST Enforcement","title":"CBIC imposes immediate interim limits on arrests, transit checks and low-value notices","body":"CBIC Instruction No. 02/2026-GST dated 30 October 2026 directs Central GST field formations, pending legislative amendments, not to make further arrests under GST; to intercept conveyances only on specific intelligence authorised in writing by an officer not below Joint Commissioner; and not to issue show-cause notices under Sections 73, 74 or 74A where the aggregate tax involved across GST laws and compensation cess is below ₹10,000. The Council has recommended the statutory amendments from 1 April 2027.","why_it_matters":"These are operative administrative directions for CBIC formations, not yet amendments to the CGST Act; parallel protection from State GST officers depends on matching State-level instructions.","action_point":"Tax and logistics teams should add the instruction to enforcement protocols, require written interception authorisation where applicable, and separately verify whether the relevant State has issued corresponding directions.","source_label":"CBIC Instruction No. 02/2026-GST text","source_url":null},{"section":"Tax & Regulatory","subsection":"GST & INDIRECT TAX","category":"GST Refunds","title":"Later filing cannot retrospectively erase pre-18 July 2022 inverted-duty refund entitlement","body":"In Kedia Agro v. Principal Commissioner, Hyderabad GST Commissionerate, APL/194/HYD/2026, GSTAT Hyderabad on 27 October 2026 remanded a ₹61.47 lakh refund claim for May 2020–March 2021. It held that Notification No. 09/2022-Central Tax (Rate), effective 18 July 2022, could not deny refund of ITC accumulated before that date merely because the fresh application was filed on 25 March 2023; an executive circular could not retrospectively curtail the accrued statutory right. Interest is also to be examined on remand.","why_it_matters":"The order separates the tax period generating accumulated credit from the later procedural filing date, materially affecting legacy refund disputes for goods added to the restricted list.","action_point":"Manufacturers with rejected legacy claims should map the accumulation period, limitation computation and any withdrawn/refiled applications before seeking restoration and interest.","source_label":"GSTAT order report and case details","source_url":null},{"section":"Capital Markets Regulation","subsection":null,"category":"Digital Accessibility","title":"SEBI moves the accessibility-audit and remediation deadline to 31 January 2027","body":"SEBI Circular HO/53/12/13(2)2026-ITD5-M2IPC/I/24856/2026 dated 30 October 2026 extends to 31 January 2027 the deadline for regulated entities to appoint an IAAP auditor, conduct accessibility audits of digital platforms and remediate findings. The extension applies across recognised exchanges, clearing corporations, depositories and registered intermediaries; all other provisions and timelines under the earlier accessibility circulars remain unchanged.","why_it_matters":"The relief is targeted, not a blanket postponement. Boards and compliance officers remain accountable for the unaffected obligations under the Rights of Persons with Disabilities framework.","action_point":"Fix an internal pre-deadline for auditor appointment, platform inventory, audit closure and evidence retention, while maintaining a separate tracker for requirements that were not extended.","source_label":"SEBI circular","source_url":null},{"section":"Startups & Growth Capital","subsection":null,"category":"Climate Finance","title":"Two Point O Capital raises $10 million to scale clean-infrastructure financing","body":"Two Point O Capital has raised $10 million in a round led by Transition Venture Capital, with Omnivore and angel investors Chiranjeev Singh Saluja and Sudhir M. Reddy participating. The Bengaluru platform combines financing, project execution and monitoring for commercial and industrial clean-energy assets. It plans to enter battery energy storage and deepen solar, energy-efficiency and wastewater-treatment offerings for sectors including data centres, automotive, pharma, manufacturing and healthcare.","why_it_matters":"The round highlights investor appetite for models that turn corporate decarbonisation from an upfront-capex decision into a financed operating solution with measurable performance.","action_point":"Industrial CFOs evaluating financed energy assets should diligence ownership, tax depreciation, GST credit, performance guarantees, termination economics and treatment of savings-linked payments.","source_label":"Funding announcement report","source_url":null},{"section":"Geopolitics & Global Trade","subsection":null,"category":"Currency & Energy Risk","title":"Elevated oil keeps the rupee exposed as markets watch US elections and Iran risk","body":"Reuters reported on 2 November that elevated crude prices are likely to keep the rupee under pressure this week, although central-bank intervention may limit abrupt moves. The currency closed Friday at ₹94.95 per US dollar after its strongest monthly gain since February. Traders are monitoring US midterm elections and the Iran conflict because renewed escalation could raise energy, freight and dollar costs for Indian importers.","why_it_matters":"India’s oil dependence creates a direct transmission channel from geopolitical escalation to working capital, landed cost, inflation and treasury exposure.","action_point":"Importers should stress-test cash flows for combined oil, freight and USD/INR shocks, and align hedges with confirmed procurement and customer pass-through clauses.","source_label":"Reuters market outlook","source_url":null}],"key_considerations":"Treat the CBIC instruction and SEBI extension as targeted operational relief rather than a dilution of underlying compliance. For cross-border payments and legacy disputes, contemporaneous documentation remains the decisive control: the new rulings reward businesses that can evidence the exact place of service, income quantum and credit-accumulation period."}$json$::jsonb, 'published', 'manual', '2026-11-02T06:37:00Z')
ON CONFLICT (slug) DO UPDATE SET content = EXCLUDED.content, ref = EXCLUDED.ref, title = EXCLUDED.title;

INSERT INTO public.briefings (slug, ref, briefing_date, title, content, status, source, sent_at)
VALUES ('2026-11-03', 'TAG/DB/2026/062', '2026-11-03', 'TAG Daily Briefing — 03 November 2026', $json${"date":"2026-11-03","ref":"TAG/DB/2026/062","topics":["Income Tax","GST","Transactions","Growth Capital","Global Trade"],"executive_summary":["The Supreme Court leaves intact reopening based on a single bogus-purchase pattern whose value crossed ₹50 lakh only after aggregation across two years.","Bombay High Court quashes a transfer-pricing assessment where the faceless officer skipped the mandatory Section 144C draft order.","GSTAT Delhi treats Expedia India’s own-account support services as exports and orders refund of ₹55.99 crore with statutory interest.","GSTN activates Rule 14B registration for qualifying e-commerce sellers without a physical place of business in the destination State."],"items":[{"section":"Tax & Regulatory","subsection":"INCOME TAX","category":"Reassessment","title":"Supreme Court leaves multi-year Section 149(1A) aggregation undisturbed","body":"In Khyati Vishal Popat v. Income Tax Officer, Civil Appeal No. 6690/2026, the Supreme Court on 29 October 2026 found no ground to interfere with the Gujarat High Court and dismissed the appeal. The High Court had upheld reopening for AY 2018–19 although the alleged bogus purchases for that year were ₹31.80 lakh, because the same proprietary concern’s linked transactions across FY 2017–18 and FY 2018–19 aggregated to ₹88.03 lakh and were treated as expenditure relating to the same pattern for Section 149(1A).","why_it_matters":"This is the material counterpoint to yesterday’s below-₹50 lakh limitation ruling: an isolated year may fall below the threshold, yet a demonstrably linked asset, expenditure, event or occasion spanning years can sustain the extended reopening window.","action_point":"In every extended-period notice, test both the year-specific escapement and the Revenue’s evidence that amounts across years arise from one qualifying asset, expenditure, event or occasion.","source_label":"Supreme Court order","source_url":null},{"section":"Tax & Regulatory","subsection":"INCOME TAX","category":"International Tax & Transfer Pricing","title":"Skipping a Section 144C draft order is an incurable jurisdictional error","body":"In Orpak Systems India Pvt. Ltd. v. Assessment Unit (NFAC), W.P. No. 424 of 2026, the Bombay High Court on 30 October 2026 quashed the final assessment for AY 2022–23. The TPO had proposed a ₹2.42 crore upward adjustment, but the faceless officer directly passed the final order without first serving the eligible assessee a draft under Section 144C(1). The Court rejected the Revenue’s request to treat the omission as a curable procedural lapse and declined an automatic remand.","why_it_matters":"The draft order is the gateway to the DRP and a substantive statutory right. A final order that bypasses it is vulnerable even where the underlying transfer-pricing adjustment may otherwise be arguable.","action_point":"Eligible assessees should verify the assessment sequence immediately on receipt of a final order and preserve a dated record of every draft, portal communication and TPO order.","source_label":"Bombay High Court order","source_url":null},{"section":"Tax & Regulatory","subsection":"GST & INDIRECT TAX","category":"Export of Services","title":"GSTAT allows Expedia India’s ₹55.99 crore export refund","body":"The GSTAT Principal Bench, New Delhi, allowed seven appeals by Expedia Online Travel Services India Pvt. Ltd. covering FY 2019–20 to FY 2022–23 and directed refund of ₹55,99,74,202 with interest under Section 56. It held that support services to overseas group entities were supplied on a principal-to-principal basis, with no authority to bind the foreign recipient and no three-party agency arrangement; they therefore fell outside “intermediary services” under Section 2(13) of the IGST Act and qualified as exports under Section 2(6).","why_it_matters":"The order reinforces substance over facilitation labels: own-account services do not become intermediary services merely because they advance the overseas customer’s commercial objective.","action_point":"Exporters of group support services should align contracts, invoices and operating evidence around own-account delivery, absence of authority to bind, and direct foreign-currency consideration.","source_label":"GSTAT final order","source_url":null},{"section":"Tax & Regulatory","subsection":"GST & INDIRECT TAX","category":"GST Registration","title":"Rule 14B opens destination-State registration without a physical presence","body":"GSTN Advisory No. 682 dated 1 November 2026 activates the simplified registration route inserted by Notification No. 05/2026–Central Tax. Eligible sellers supplying goods exclusively through e-commerce operators that collect TCS may register in a State or Union Territory where they lack a physical place of business, using an approved operator warehouse address. The applicant must have an active regular GSTIN under the same PAN in another State; one Rule 14B registration is permitted per PAN per State, and output tax on B2B supplies cannot exceed ₹2.5 lakh per month.","why_it_matters":"The route lowers the fixed-cost barrier to multi-State fulfilment, but it is a tightly conditioned operating model rather than a general exemption from place-of-business requirements.","action_point":"Marketplace sellers should map State-wise B2B liability, warehouse approvals, home-State GSTIN status and exclusivity to e-commerce supplies before opting in.","source_label":"GSTN Advisory No. 682","source_url":null},{"section":"M&A, Transactions & Investment","subsection":null,"category":"Corporate Reorganisation","title":"ITC moves to absorb Yoga Bar owner Sproutlife Foods","body":"ITC’s board on 2 November 2026 approved a scheme under Sections 230–232 of the Companies Act to amalgamate wholly owned Sproutlife Foods Pvt. Ltd., owner of the Yoga Bar brand, into ITC. The appointed date is 1 April 2026, subject to statutory approvals. Because Sproutlife is wholly owned, its shares will be cancelled on effectiveness; no new ITC shares are proposed and the parent’s shareholding pattern will not change.","why_it_matters":"The internal merger converts ITC’s completed acquisition into direct operating integration, enabling a simpler structure, consolidated resources and potential procurement and distribution synergies without equity dilution.","action_point":"Boards planning post-acquisition simplification should prepare an appointed-date tax, accounting, contract, licence and employee migration workstream before seeking scheme approvals.","source_label":"ITC stock-exchange announcement","source_url":null},{"section":"Startups & Growth Capital","subsection":null,"category":"Healthtech Funding","title":"Clinics On Cloud raises ₹120 crore to take its microclinic model overseas","body":"Pune-based Clinics On Cloud announced a ₹120 crore (US$12.5 million) Series A from Dubai-based Model42 at a ₹600 crore valuation. The company, which reports more than 3,500 installations and 12 million health screenings across eight countries, will use the capital for AI-led diagnostics, R&D, manufacturing scale-up and international regulatory compliance. The UAE will serve as its hub for planned expansion into Africa, the United States and Southeast Asia.","why_it_matters":"The round combines Indian health-device manufacturing with cross-border preventive-care infrastructure, placing regulatory approvals, data governance and clinical validation at the centre of value creation.","action_point":"Healthtech founders pursuing international expansion should build a jurisdiction-by-jurisdiction plan for device registration, patient-data transfers, AI validation, product liability and local distribution.","source_label":"Company funding announcement","source_url":null},{"section":"Geopolitics & Global Trade","subsection":null,"category":"India–UK Trade","title":"India signals resolution of the bulk-Scotch tariff dispute","body":"Reuters reported on 2 November that Indian commerce officials assured liquor-industry executives the government would honour the India–UK trade pact and address the disputed treatment of bulk Scotch. The pact, implemented in July, reduced the Scotch tariff from 150% to 75%, but tax authorities had questioned whether the concession covered bulk imports used in Indian-made foreign liquor and had initiated investigations involving major distillers.","why_it_matters":"A formal resolution would affect landed cost, inventory valuation and pricing for Diageo, Pernod Ricard, Radico Khaitan, Allied Blenders and other businesses reliant on bulk Scotch inputs; the reported assurance is not yet a published customs clarification.","action_point":"Importers should preserve classification and origin records, quantify exposure under both tariff interpretations and avoid changing provisioning until an authoritative customs direction is issued.","source_label":"Reuters","source_url":null}],"key_considerations":"Today’s decisions reward precise operating evidence. For reassessment, the decisive question is whether multiple-year amounts truly relate to one qualifying event; for export refunds, it is who supplies what, to whom and on whose account. Businesses entering simplified GST registration or overseas healthtech markets should treat eligibility and local compliance as continuing controls, not one-time onboarding checks."}$json$::jsonb, 'published', 'manual', '2026-11-03T06:37:00Z')
ON CONFLICT (slug) DO UPDATE SET content = EXCLUDED.content, ref = EXCLUDED.ref, title = EXCLUDED.title;

